"use client";
/* Bitbug, from the Piixpal shadcn registry. Options: https://piixpal.vercel.app/components/ */
import * as React from "react";
import { loadPiixpal, piixAttrs, type PiixProps } from "@/lib/piixpal";

export function Bitbug(props: PiixProps) {
  React.useEffect(() => { loadPiixpal("bitbug"); }, []);
  return React.createElement("piix-pal", { "pal": "bitbug", ...piixAttrs(props) });
}

export default Bitbug;
